// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { 
  useCurrentFrame, 
  useVideoConfig, 
  AbsoluteFill, 
  spring, 
  interpolate, 
  Easing 
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');
import { Star } from "@remotion/shapes";

const { fontFamily: interFamily } = loadInter();
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();



export type MilestoneAnimationProps = Record<string, any>;

const MilestoneAnimation: React.FC<MilestoneAnimationProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = false,
  durationInSeconds = 6,
  milestoneValue = 70000,
  titleText = "MALLOY STUDIO",
  subtitleText = "Graduates Worldwide",
  primaryColor = "#ffffff",
  accentColor = "#fbbf24",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parser Safety Variables
  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  const isPortrait = width < height;
  const layoutDirection = isPortrait ? "column" : "row";
  const flexAlign = isPortrait ? "center" : "flex-start";
  const textAlign = isPortrait ? "center" : "left";

  // Responsive Sizing Basics
  const baseSize = Math.min(width, height);
  const hatSize = baseSize * 0.35;
  const gapSize = baseSize * 0.1;
  const titleSize = baseSize * 0.025;
  const numberSize = baseSize * 0.15;
  const subtitleSize = baseSize * 0.04;

  // Star Burst Variables
  const starsArray = Array.from({ length: 8 }).map((_, i) => ({
    angle: (i / 8) * Math.PI * 2,
    key: i,
  }));
  const maxBurstDist = hatSize * 0.55;
  const starInnerR = hatSize * 0.02;
  const starOuterR = hatSize * 0.05;

  // Animations - Hat
  const hatScale = spring({
    fps,
    frame: frame - 10,
    config: { damping: 12, stiffness: 80 },
  });

  const floatY = Math.sin(frame / 15) * (baseSize * 0.01);

  const swingSpring = spring({
    fps,
    frame: frame - 15,
    config: { damping: 5, mass: 1, stiffness: 20 },
  });

  const tasselRot = interpolate(swingSpring, [0, 1], [60, 0]);
  const hatRotation = interpolate(swingSpring, [0, 1], [-10, 0]);

  // Animations - Text Content
  const titleOpacity = interpolate(frame, [25, 40], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  const titleY = interpolate(frame, [25, 40], [20, 0], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  const numberScaleSpring = spring({
    fps,
    frame: frame - 25,
    config: { damping: 12 },
  });
  const numberScale = interpolate(numberScaleSpring, [0, 1], [0.9, 1]);
  const numberOpacity = interpolate(frame, [25, 40], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  const currentNumber = Math.floor(
    interpolate(frame, [30, 100], [0, milestoneValue], {
      easing: Easing.out(Easing.exp),
      extrapolateRight: "clamp",
      extrapolateLeft: "clamp",
    })
  );

  const subtitleOpacity = interpolate(frame, [45, 60], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  const subtitleY = interpolate(frame, [45, 60], [20, 0], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div
        style={{
          display: "flex",
          flexDirection: layoutDirection,
          alignItems: "center",
          justifyContent: "center",
          gap: gapSize,
          width: "100%",
          height: "100%",
          padding: baseSize * 0.1,
          boxSizing: "border-box",
        }}
      >
        {/* LEFT: Hat & Stars Wrapper */}
        <div style={{ position: "relative", width: hatSize, height: hatSize }}>
          {/* Confetti Stars */}
          {starsArray.map((star) => {
            const burstSpring = spring({
              fps,
              frame: frame - 10,
              config: { damping: 12 },
            });
            const distance = burstSpring * maxBurstDist;
            const x = Math.cos(star.angle) * distance;
            const y = Math.sin(star.angle) * distance;
            const starScale = interpolate(frame, [15, 35], [1, 0], {
              extrapolateRight: "clamp",
              extrapolateLeft: "clamp",
            });
            const starRotation = frame * 2;

            return (
              <Star
                key={star.key}
                points={5}
                innerRadius={starInnerR}
                outerRadius={starOuterR}
                fill={accentColor}
                style={{
                  position: "absolute",
                  left: "50%",
                  top: "50%",
                  transform: `translate(-50%, -50%) translate(${x}px, ${y}px) scale(${starScale}) rotate(${starRotation}deg)`,
                }}
              />
            );
          })}

          {/* Student Hat Shape */}
          <div
            style={{
              width: "100%",
              height: "100%",
              transform: `scale(${hatScale}) translateY(${floatY}px) rotate(${hatRotation}deg)`,
              filter: "drop-shadow(0px 15px 25px rgba(0,0,0,0.4))",
            }}
          >
            <svg
              viewBox="0 0 100 100"
              style={{ width: "100%", height: "100%", overflow: "visible" }}
            >
              {/* Cap Base with lower opacity for depth */}
              <path
                d="M 20,41.67 L 20,70 Q 50,90 80,70 L 80,41.67 L 50,55 Z"
                fill={primaryColor}
                opacity={0.8}
              />

              {/* Top Board Diamond */}
              <polygon
                points="50,15 95,35 50,55 5,35"
                fill={primaryColor}
              />

              {/* Swinging Tassel Group */}
              <g
                style={{
                  transformOrigin: "50px 35px",
                  transform: `rotate(${tasselRot}deg)`,
                }}
              >
                {/* String */}
                <path
                  d="M 50,35 C 58,45 58,55 50,70"
                  fill="none"
                  stroke={accentColor}
                  strokeWidth="1.5"
                />
                {/* Tassel Brush */}
                <polygon
                  points="50,70 42,88 58,88"
                  fill={accentColor}
                />
              </g>

              {/* Tassel Button Core */}
              <ellipse cx="50" cy="35" rx="5" ry="3" fill={accentColor} />
            </svg>
          </div>
        </div>

        {/* RIGHT: Text Content */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: flexAlign,
            textAlign: textAlign,
            maxWidth: width * 0.6,
          }}
        >
          {/* Title */}
          <div
            style={{
              opacity: titleOpacity,
              transform: `translateY(${titleY}px)`,
              color: accentColor,
              fontWeight: 700,
              letterSpacing: "0.2em",
              fontSize: titleSize,
              marginBottom: baseSize * 0.02,
              fontFamily: interFamily,
              textTransform: "uppercase",
            }}
          >
            {titleText}
          </div>

          {/* Large Number Milestone */}
          <div
            style={{
              opacity: numberOpacity,
              transform: `scale(${numberScale})`,
              color: primaryColor,
              fontSize: numberSize,
              fontWeight: 800,
              lineHeight: 1,
              fontFamily: spaceGroteskFamily,
              fontVariantNumeric: "tabular-nums",
              textShadow: "0px 10px 30px rgba(0,0,0,0.2)",
            }}
          >
            {currentNumber.toLocaleString("en-US")}
          </div>

          {/* Subtitle */}
          <div
            style={{
              opacity: subtitleOpacity * 0.8,
              transform: `translateY(${subtitleY}px)`,
              color: primaryColor,
              fontSize: subtitleSize,
              marginTop: baseSize * 0.02,
              fontFamily: interFamily,
              fontWeight: 400,
            }}
          >
            {subtitleText}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default MilestoneAnimation;